429	/// Print `WARNING` lines when the finished run's tail-sensitive
430	/// stats — `max` and the untrimmed mean/stdev — are poisoned:
431	///
432	/// - the system suspended during the run (clock divergence — a
433	///   mid-sample suspend inflates that sample by the sleep gap,
434	///   even under the histogram bound);
435	/// - one or more samples clamped at [`HIST_HIGH_PS`] (a wedged or
436	///   suspend-inflated sample with no detected suspend).
437	///
438	/// A few inflated samples out of millions land in the extreme
439	/// tail band: percentile boundaries and the trimmed non-tail
440	/// stats are unaffected, so the flag names what died rather than
441	/// condemning the whole report. Called at the end of
442	/// [`print_report`] so the flag is the last thing in the bench's
443	/// report, where it can't scroll out of mind. Prints one
444	/// `WARNING {name}:` header with each finding indented below it,
445	/// keeping the findings visible next to the long bench name.
446	fn warn_invalid(name: &str, hist: &Histogram<u64>, suspended_s: f64) {
447	    let mut findings: Vec<String> = Vec::new();
448	    if suspended_s >= SUSPEND_WARN_S {
449	        findings.push(format!(
450	            "system suspended ~{suspended_s:.1}s during the run; max/mean/stdev poisoned"
451	        ));
452	    }
453	    if !hist.is_empty() && hist.max() >= HIST_HIGH_PS {
454	        findings.push(format!(
455	            "sample(s) clamped at the {}s histogram bound; max/mean/stdev poisoned",
456	            HIST_HIGH_PS / 1_000_000_000_000
457	        ));
458	    }
459	    if !findings.is_empty() {
460	        println!("WARNING {name}:");
461	        for finding in &findings {
462	            println!("  {finding}");
463	        }
464	    }
465	}
466	
467	/// Format an integer with thousands separators, e.g.
468	/// `12345` → `"12,345"`.
469	pub fn fmt_commas(n: u64) -> String {
470	    let s = n.to_string();
471	    let mut result = String::new();
472	    for (i, c) in s.chars().rev().enumerate() {
473	        if i > 0 && i % 3 == 0 {
474	            result.push(',');
475	        }
476	        result.push(c);
477	    }
478	    result.chars().rev().collect()
