/// Print `WARNING` lines when the finished run's tail-sensitive
/// stats — `max` and the untrimmed mean/stdev — are poisoned:
///
/// - the system suspended during the run (clock divergence — a
///   mid-sample suspend inflates that sample by the sleep gap,
///   even under the histogram bound);
/// - one or more samples clamped at [`HIST_HIGH_PS`] (a wedged or
///   suspend-inflated sample with no detected suspend).
///
/// A few inflated samples out of millions land in the extreme
/// tail band: percentile boundaries and the trimmed non-tail
/// stats are unaffected, so the flag names what died rather than
/// condemning the whole report. Called at the end of
/// [`print_report`] so the flag is the last thing in the bench's
/// report, where it can't scroll out of mind. Prints one
/// `WARNING {name}:` header with each finding indented below it,
/// keeping the findings visible next to the long bench name.
fn warn_invalid(name: &str, hist: &Histogram<u64>, suspended_s: f64) {
    let mut findings: Vec<String> = Vec::new();
    if suspended_s >= SUSPEND_WARN_S {
        findings.push(format!(
            "system suspended ~{suspended_s:.1}s during the run; max/mean/stdev poisoned"
        ));
    }
    if !hist.is_empty() && hist.max() >= HIST_HIGH_PS {
        findings.push(format!(
            "sample(s) clamped at the {}s histogram bound; max/mean/stdev poisoned",
            HIST_HIGH_PS / 1_000_000_000_000
        ));
    }
    if !findings.is_empty() {
        println!("WARNING {name}:");
        for finding in &findings {
            println!("  {finding}");
        }
    }
}

/// Format an integer with thousands separators, e.g.
/// `12345` → `"12,345"`.
pub fn fmt_commas(n: u64) -> String {
    let s = n.to_string();
    let mut result = String::new();
    for (i, c) in s.chars().rev().enumerate() {
        if i > 0 && i % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result.chars().rev().collect()
}

/// Format a float with `decimals` fractional digits and thousands
/// separators on the integer part.
pub fn fmt_commas_f64(n: f64, decimals: usize) -> String {
    let s = format!("{n:.decimals$}");
    let (sign, body) = match s.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", s.as_str()),
    };
    let (int_part, frac_part) = match body.find('.') {
        Some(i) => (&body[..i], &body[i..]),
        None => (body, ""),
    };
    let int_num: u64 = int_part.parse().unwrap_or(0);
    format!("{sign}{}{frac_part}", fmt_commas(int_num))
}

/// Index of the band containing `mid_rank`, over the full boundary
/// ladder `bounds` (`n_bands = bounds.len() - 1`).
///
/// - Bands are **right-closed** `(lower, upper]`: a rank exactly on a
///   boundary falls in the band that boundary *caps* — a single
///   sample's mid-rank of 0.5 lands in `p50`, not `p60`. This matches
///   the upper-boundary row labels and the CDF reading of a
///   percentile (value at or below which that fraction of samples
///   falls). See [`print_report`] for the convention and references.
/// - `mid_rank` is the Hazen plotting position `(i - 0.5) / n` of the
///   sample's rank, computed by the caller.
fn band_index(mid_rank: f64, bounds: &[bands::Boundary]) -> usize {
    let n_bands = bounds.len() - 1;
    bounds[1..]
        .iter()
        .position(|b| mid_rank <= b.pct)
        .unwrap_or(n_bands - 1)
}

/// Build the trimmed-stat range label from the populated bands
/// below the n2 ≡ p99 tail cut.
///
/// - Names the first..last populated band in `band_count[..trim_bands]`
///   by its **upper** boundary (`bounds[i + 1]`), matching the row
///   labels — so the label tracks the real extent of the trimmed
///   data rather than asserting a `min` row (never printed — rows use
///   upper boundaries) or an `n2` band that can be empty.
/// - Collapses to a single name when one band holds all the trimmed
///   data (`p60`, not `p60..p60`).
/// - Empty string when no trimmed band is populated — only with no
///   samples at all, where the caller's `trim` is `None` and the
///   label goes unused.
fn trim_range_label(
    bounds: &[bands::Boundary],
    band_count: &[u64],
    trim_bands: usize,
    style: BandLabels,
) -> String {
    let first = (0..trim_bands).find(|&i| band_count[i] > 0);
    let last = (0..trim_bands).rev().find(|&i| band_count[i] > 0);
    match (first, last) {
        (Some(f), Some(l)) if f == l => bounds[f + 1].trim_name(style).to_string(),
        (Some(f), Some(l)) => format!(
            "{}..{}",
            bounds[f + 1].trim_name(style),
            bounds[l + 1].trim_name(style),
        ),
        _ => String::new(),
    }
}

/// Print the full bench report: header line (logfmt-style metadata),
/// per-band histogram, whole-histogram mean/stdev, and trimmed

/// Environment-grade thresholds, one array per signal: the
/// ascending cutoffs a signal crosses to score B, C, D, F (below
/// the first is A). The overall letter is the worst signal.
///
/// - **Provisional** — seeded from quiet-3900X spread on
///   2026-07-25; the -5 validation pass on both boxes is meant
///   to tune them. The design constraint: a quiet release-build
///   machine should essentially never leave A/B, because a
///   false alarm every third run destroys trust in the warning.
/// - WARNINGs print only at D or worse; C is visible in the
///   always-printed grade line without shouting. First
///   measurements: a quiet 3900X graded B (debug included), a
///   restless one C, and a cross-attempt frequency-regime shift
///   D with its warning — the intended spread.
pub mod grade_thresholds {
    /// Disturbed-sample fraction (worst of d_low / d_high).
    pub const DISTURBED: [f64; 4] = [0.005, 0.02, 0.05, 0.15];
    /// Dirty-window fraction (worst of d_low / d_high).
    pub const DIRTY_WINDOWS: [f64; 4] = [0.25, 0.50, 0.75, 0.90];
    /// Loop-only floor drift across the calibration bracket.
    pub const DRIFT: [f64; 4] = [0.01, 0.02, 0.05, 0.10];
    /// Worst relative residual of a ladder point vs the line.
    pub const RESID: [f64; 4] = [0.01, 0.02, 0.05, 0.10];
    /// Loop-only vs dithered-fit slope divergence.
    pub const CROSS: [f64; 4] = [0.02, 0.05, 0.10, 0.20];
    /// Worst relative constant change between clean attempts.
    pub const REPEAT: [f64; 4] = [0.025, 0.05, 0.10, 0.20];
}

/// Score one signal against its [`grade_thresholds`] array:
/// 0 (A) through 4 (F) — the count of cutoffs crossed.
fn grade_score(x: f64, cutoffs: [f64; 4]) -> u8 {
    cutoffs.iter().filter(|&&c| x > c).count() as u8
}

/// The environment grade: the always-printed synthesis of the
/// calibration self-checks. Signals are facts about the run;
/// `letter` is the worst signal's grade ('F' outright when the
/// published attempt carries physical violations).
///
/// - See notes/chores/chores-04.md#replanning-slope-dither-and-self-checks
///   for the design: every check runs every time, a passing
///   check is silent, and the one always-visible line carries
///   the letter plus the evidence behind it.
#[derive(Debug)]
pub struct CalGrade {
    /// Fraction of dithered samples above [`DISTURBED_MULT`] x
    /// the low-quantile floor (worst of the two points).
    pub disturbed_frac: f64,
    /// Fraction of dithered windows above [`DIRTY_WINDOW_TOL`]
    /// over the minimum window mean (worst of the two points).
    pub dirty_window_frac: f64,
    /// `|l_end - l_start| / l_start` over the loop-only bracket
    /// passes — machine-state drift across the calibration.
    pub drift_frac: f64,
    /// Worst `|residual| / value` of a ladder point against the
    /// Theil-Sen line (median-intercept anchored).
    pub max_resid_frac: f64,
    /// `|fit_slope - slope| / slope`, dithered two-point fit vs
    /// the production loop-only slope.
    pub slope_cross_frac: f64,
    /// Worst relative constant change between the last two clean
    /// attempts; `None` when fewer than two attempts came out
    /// clean (scored as C at best).
    pub repeat_rel: Option<f64>,
    /// Largest absolute change of frame/call or frame/sample
    /// between the last two clean attempts, in ns — the headline
    /// "constants repeat to ±X ns" number.
    pub repeat_ns: Option<f64>,
    /// Overall letter, worst signal wins: A, B, C, D, or F.
    pub letter: char,
}

impl CalGrade {
    /// Worst per-signal score (0=A .. 4=F), with an unknown
    /// repeatability floored at C — if two clean attempts never
    /// happened, the environment has already said something.
    fn score(&self) -> u8 {
        let repeat_score = match self.repeat_rel {
            Some(r) => grade_score(r, grade_thresholds::REPEAT),
            None => 2,
        };
        [
            grade_score(self.disturbed_frac, grade_thresholds::DISTURBED),
            grade_score(self.dirty_window_frac, grade_thresholds::DIRTY_WINDOWS),
            grade_score(self.drift_frac, grade_thresholds::DRIFT),
            grade_score(self.max_resid_frac, grade_thresholds::RESID),
            grade_score(self.slope_cross_frac, grade_thresholds::CROSS),
            repeat_score,
        ]
        .into_iter()
        .fold(0, u8::max)
    }
}

